(function(){
  var $=function(id){return document.getElementById(id)};
  // Each recipe declares its fields, how to build the formula, and what the
  // classic mistake is. Adding one is a matter of adding an entry here.
  var R=[
    { id:'vlookup', name:'VLOOKUP',
      f:[['what','What to look up','A2'],['where','Table to search','Sheet2!A:D'],
         ['col','Which column to return (1 = first)','4'],['exact','Exact match','yes']],
      build:function(v){ return '=VLOOKUP('+v.what+','+v.where+','+v.col+','+(v.exact==='no'?'TRUE':'FALSE')+')'; },
      why:'Looks for the value in the FIRST column of the table and returns something from the column you numbered.',
      tip:'VLOOKUP can only look to the right. If what you are matching sits to the right of what you want back, use INDEX and MATCH instead, or XLOOKUP if you have Excel 365.' },
    { id:'xlookup', name:'XLOOKUP',
      f:[['what','What to look up','A2'],['lookIn','Column to search','Sheet2!A:A'],
         ['giveBack','Column to return','Sheet2!D:D'],['notFound','If nothing matches','"Not found"']],
      build:function(v){ return '=XLOOKUP('+v.what+','+v.lookIn+','+v.giveBack+','+v.notFound+')'; },
      why:'Searches one column and returns the matching row from another. The columns can be in any order.',
      tip:'XLOOKUP needs Excel 365 or Excel 2021. In older versions it shows as <code>_xlfn.XLOOKUP</code> and returns an error, so use VLOOKUP or INDEX and MATCH there.' },
    { id:'indexmatch', name:'INDEX MATCH',
      f:[['giveBack','Column to return','Sheet2!D:D'],['what','What to look up','A2'],['lookIn','Column to search','Sheet2!C:C']],
      build:function(v){ return '=INDEX('+v.giveBack+',MATCH('+v.what+','+v.lookIn+',0))'; },
      why:'MATCH finds the row number, INDEX pulls the value from that row. Works in every direction.',
      tip:'The <code>0</code> at the end of MATCH means exact match. Leave it out and Excel assumes your data is sorted and returns quietly wrong answers.' },
    { id:'sumif', name:'SUMIF',
      f:[['range','Column to test','B:B'],['crit','Condition','"Lahore"'],['sum','Column to add up','D:D']],
      build:function(v){ return '=SUMIF('+v.range+','+v.crit+','+v.sum+')'; },
      why:'Adds up the numbers in one column, but only on the rows where another column meets your condition.',
      tip:'Text conditions need quotes: <code>"Lahore"</code>. Comparisons go inside quotes too: <code>"&gt;100"</code>. To point at a cell instead, write <code>"&gt;"&amp;E1</code>.' },
    { id:'sumifs', name:'SUMIFS',
      f:[['sum','Column to add up','D:D'],['r1','First column to test','B:B'],['c1','First condition','"Lahore"'],
         ['r2','Second column to test','C:C'],['c2','Second condition','">100"']],
      build:function(v){ return '=SUMIFS('+v.sum+','+v.r1+','+v.c1+','+v.r2+','+v.c2+')'; },
      why:'Same as SUMIF but with two or more conditions, all of which must be true.',
      tip:'The order is the opposite of SUMIF: the column being added comes FIRST in SUMIFS and LAST in SUMIF. This catches almost everyone.' },
    { id:'countif', name:'COUNTIF',
      f:[['range','Column to count in','B:B'],['crit','Condition','"Lahore"']],
      build:function(v){ return '=COUNTIF('+v.range+','+v.crit+')'; },
      why:'Counts how many cells meet the condition.',
      tip:'To find duplicates, put <code>=COUNTIF(A:A,A2)&gt;1</code> next to row 2 and fill down. Anything showing TRUE appears more than once.' },
    { id:'if', name:'IF',
      f:[['test','Condition','D2>1000'],['yes','If true','"Big"'],['no','If false','"Small"']],
      build:function(v){ return '=IF('+v.test+','+v.yes+','+v.no+')'; },
      why:'Returns one thing when the condition holds and another when it does not.',
      tip:'Text results need quotes, numbers do not. To nest a second test, put another IF where the false result goes.' },
    { id:'iferror', name:'IFERROR',
      f:[['formula','Your formula','VLOOKUP(A2,Sheet2!A:D,4,FALSE)'],['fallback','Show instead of the error','""']],
      build:function(v){ return '=IFERROR('+String(v.formula).replace(/^=/,'')+','+v.fallback+')'; },
      why:'Runs your formula and shows something friendlier if it fails.',
      tip:'Useful, but hide errors carefully. IFERROR also swallows real mistakes like a typo in a range, so a blank column can mean everything failed rather than nothing matched.' },
    { id:'textjoin', name:'Join columns',
      f:[['sep','Put between them','", "'],['skip','Skip empty cells','yes'],['cells','Cells to join','A2,B2,C2']],
      build:function(v){ return '=TEXTJOIN('+v.sep+','+(v.skip==='no'?'FALSE':'TRUE')+','+v.cells+')'; },
      why:'Joins several cells into one with a separator, without leaving stray separators where a cell is blank.',
      tip:'TEXTJOIN needs Excel 2019 or later. Before that, use <code>=A2&amp;", "&amp;B2</code>, which does leave the separator when a cell is empty.' },
    { id:'split', name:'Split first and last name',
      f:[['cell','Cell holding the full name','A2']],
      build:function(v){ return 'First:  =LEFT('+v.cell+',FIND(" ",'+v.cell+')-1)\nLast:   =MID('+v.cell+',FIND(" ",'+v.cell+')+1,LEN('+v.cell+'))'; },
      why:'Two formulas: one takes everything before the first space, the other everything after it.',
      tip:'Names with three parts put the middle name into Last. If the cell has no space at all, FIND returns an error, so wrap each in IFERROR.' },
    { id:'datediff', name:'Days between dates',
      f:[['from','Earlier date cell','A2'],['to','Later date cell','B2'],['unit','Count in','days']],
      build:function(v){
        if(v.unit==='days') return '='+v.to+'-'+v.from;
        var u=v.unit==='months'?'"M"':(v.unit==='years'?'"Y"':'"D"');
        return '=DATEDIF('+v.from+','+v.to+','+u+')';
      },
      why:'Excel stores dates as numbers, so subtracting gives whole days. DATEDIF handles whole months and years.',
      tip:'Format the answer cell as Number, not Date, or Excel shows your 30 as the 30th of January 1900.' },
    { id:'percent', name:'Percentage change',
      f:[['old','Original value cell','A2'],['nw','New value cell','B2']],
      build:function(v){ return '=('+v.nw+'-'+v.old+')/ABS('+v.old+')'; },
      why:'The difference divided by the original. Format the cell as a percentage.',
      tip:'ABS around the original is what makes negatives behave: without it, a rise from -50 to -25 shows as a fall.' }
  ];
  var cur=R[0], vals={};
  function buildTabs(){
    $('tabs').innerHTML=R.map(function(r){
      return '<button type="button" data-id="'+r.id+'"'+(r.id===cur.id?' class="active"':'')+'>'+r.name+'</button>';
    }).join('');
  }
  function buildForm(){
    vals={};
    $('form').innerHTML='<div class="row">'+cur.f.map(function(f){
      var isYesNo = f[2]==='yes';
      var input = isYesNo
        ? '<select id="f_'+f[0]+'"><option value="yes">Yes</option><option value="no">No</option></select>'
        : '<input type="text" id="f_'+f[0]+'" value="'+String(f[2]).replace(/"/g,'&quot;')+'">';
      return '<label><span>'+f[1]+'</span>'+input+'</label>';
    }).join('')+'</div>';
    cur.f.forEach(function(f){
      vals[f[0]]=f[2];
      var el=$('f_'+f[0]);
      el.addEventListener('input',update); el.addEventListener('change',update);
    });
    update();
  }
  function update(){
    cur.f.forEach(function(f){ vals[f[0]]=$('f_'+f[0]).value; });
    $('out').textContent=cur.build(vals);
    $('why').textContent=cur.why;
    $('tip').innerHTML='<b>Worth knowing</b>'+cur.tip;
    if(window.WT) WT.resize();
  }
  $('tabs').addEventListener('click',function(e){
    var b=e.target.closest('button[data-id]'); if(!b) return;
    cur=R.filter(function(r){return r.id===b.dataset.id})[0];
    buildTabs(); buildForm();
  });
  $('copy').addEventListener('click',function(){
    var ok=WT.copy($('out').textContent);
    this.textContent=ok?'Copied':'Press Ctrl+C';
    var b=this; setTimeout(function(){b.textContent='Copy formula'},1400);
  });
  $('reset').addEventListener('click',buildForm);
  buildTabs(); buildForm();
})();
